import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final Set<String> VALID_REPORTS = Set.of("quarterly", "annual", "audit");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String clientId = req.getParameter("client_id");
        String fiscal_year = req.getParameter("year");

        // Validate report type against allowlist
        if (reportType == null || !VALID_REPORTS.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Client ID format check
        if (clientId == null || !clientId.matches("^[A-Z]{2}[0-9]{6}$")) {
            resp.sendError(400, "Invalid client ID format");
            return;
        }

        // Build template path - reportType is validated above
        String templatePath = TEMPLATE_DIR + reportType + ".xml";
        String template = readFile(templatePath);

        // Substitute variables into template
        Map<String, String> vars = new HashMap<>();
        vars.put("CLIENT_ID", clientId);
        vars.put("FISCAL_YEAR", fiscal_year);
        vars.put("GENERATED_AT", new java.text.SimpleDateFormat("yyyy-MM-dd").format(new Date()));
        vars.put("SERVER_NODE", System.getenv("HOSTNAME"));

        StringSubstitutor sub = new StringSubstitutor(vars);
        String result = sub.replace(template);

        resp.setContentType("application/xml");
        resp.getWriter().write(result);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Custom report generation with user-supplied XSLT
        String clientId = req.getParameter("client_id");
        String xsltContent = req.getParameter("stylesheet");
        String dataSource = req.getParameter("datasource");

        if (clientId == null || !clientId.matches("^[A-Z]{2}[0-9]{6}$")) {
            resp.sendError(400, "Invalid client ID");
            return;
        }

        if (xsltContent == null || xsltContent.length() > 8192) {
            resp.sendError(400, "Stylesheet required (max 8KB)");
            return;
        }

        // Apply XSLT transformation
        try {
            javax.xml.transform.TransformerFactory tf = 
                javax.xml.transform.TransformerFactory.newInstance();
            javax.xml.transform.Source xsltSource = 
                new javax.xml.transform.stream.StreamSource(
                    new StringReader(xsltContent));
            javax.xml.transform.Transformer transformer = tf.newTransformer(xsltSource);

            // Load data from configured source
            String dataPath = "/opt/reports/data/" + clientId + "/" + 
                             (dataSource != null ? dataSource : "default") + ".xml";
            javax.xml.transform.Source xmlSource = 
                new javax.xml.transform.stream.StreamSource(new File(dataPath));

            StringWriter output = new StringWriter();
            javax.xml.transform.Result xmlResult = 
                new javax.xml.transform.stream.StreamResult(output);
            transformer.transform(xmlSource, xmlResult);

            resp.setContentType("application/xml");
            resp.getWriter().write(output.toString());
        } catch (javax.xml.transform.TransformerException e) {
            resp.sendError(500, "Transform failed: " + e.getMessage());
        }
    }

    private String readFile(String path) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }
}
